def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def fibonacci(n: int) -> int:
        a = 0
        b = 1
        if n <= 1:
            return a
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

    if is_prime(n) and is_prime(fibonacci(n)):
        return fibonacci(n)
    else:
        return 0
